package user

import (
	"testing"

	"github.com/WiscWebGroup/photoly/photoly_server/internal/user/legacy"
)

// Hashes below were generated by werkzeug.security.generate_password_hash (python:3.12-slim, pip werkzeug).
func TestWerkzeugHashes(t *testing.T) {
	scrypt := "scrypt:32768:8:1$O7qlAE1GmFpaBQcF$fba91b07c749cbea4ef28bf182330d2d218cc1dc30910657f28d3a7bb14aa622311de1ef4c09ec9b4d5cf6187e72d1cb231a3f39a5c378f5da63c2cd7655e77f"
	pbkdf2 := "pbkdf2:sha256:1000$HlZtjO4WkrJ7spqE$3e1481507fbe94547dc07eb6b6b7c185363a04af5e9bceeb830822695e799782"
	for _, c := range []struct {
		hash, pw string
		ok       bool
	}{{scrypt, "pässword1", true}, {scrypt, "password1", false}, {pbkdf2, "secret", true}, {pbkdf2, "Secret", false}, {"garbage", "x", false}} {
		if got := legacy.CheckPassword(c.hash, c.pw); got != c.ok {
			t.Errorf("CheckPassword(%.20s, %q) = %v", c.hash, c.pw, got)
		}
	}
	h := legacy.HashPassword("round trip")
	if !legacy.CheckPassword(h, "round trip") || legacy.CheckPassword(h, "nope") || h[:17] != "scrypt:32768:8:1$" {
		t.Errorf("round trip failed: %s", h)
	}
}
